import assert from 'node:assert/strict';
import { test } from 'node:test';
import { mdToSvelte } from '@sveltepress/vite';
import { compile } from 'svelte/compiler';
import {
  protectDesignExamples,
  rewriteDocumentLinks
} from './sync-design-docs.ts';

const generatedNotice =
  '<!-- Generated by scripts/sync-design-docs.ts. Edit the source in docs/. -->';

async function compileExample(
  source: string,
  generated = true
): Promise<string> {
  const { code } = await mdToSvelte({
    mdContent: `${generated ? generatedNotice : ''}\n\n${source}`,
    filename: 'example.md',
    remarkPlugins: [protectDesignExamples]
  });
  compile(code, { filename: 'Example.svelte', generate: 'server' });
  return code;
}

test('inline examples survive Markdown and Svelte compilation as literal text', async () => {
  const code = await compileExample(
    'IDs: `${mapId}:${layerId}`, `<script lang="ts">`, `@cii/*`, `--cii-*`, ' +
      '`peerDependenciesMeta: { "x": { "optional": true } }`, ' +
      '`signInWithOtp({ email, options: { shouldCreateUser: true, captchaToken } })`, ' +
      '`{ sent: true, email }`, `a_b * c & d < e`, and `` a `tick` ``.'
  );
  assert.ok(
    code.includes('<code>$&#123;mapId&#125;:$&#123;layerId&#125;</code>')
  );
  assert.ok(code.includes('<code>&lt;script lang="ts"&gt;</code>'));
  assert.ok(code.includes('<code>@cii/*</code>'));
  assert.ok(code.includes('<code>--cii-*</code>'));
  assert.ok(code.includes('<code>a_b * c &amp; d &lt; e</code>'));
  assert.ok(code.includes('<code>a `tick`</code>'));
  assert.ok(!code.includes('<em>'));
});

test('prose braces display literally, including in Markdown tables', async () => {
  const code = await compileExample(
    'A {literal} value.\n\n| Result |\n| --- |\n| `{ sent: true, email }` |'
  );
  assert.ok(code.includes('A &#123;literal&#125; value.'));
  assert.ok(
    code.includes('<td><code>&#123; sent: true, email &#125;</code></td>')
  );
});

test('fenced examples stay code and authored SveltePress pages keep expressions', async () => {
  const code = await compileExample('```ts\nconst id = 1;\n```');
  assert.ok(code.includes('<pre><code'));
  const authored = await compileExample('`{ sent: true }`', false);
  assert.ok(authored.includes('<code>{`{ sent: true }`}</code>'));
});

test('published links resolve between current and nested archive pages, preserving anchors', () => {
  const current = rewriteDocumentLinks(
    '[Earlier](./mapping-components-spec.md#scope)',
    'mapping'
  );
  const archive = rewriteDocumentLinks(
    '[Current](./svelte-mapping-components-development-plan.md)',
    'archive/mapping-spec'
  );
  const base = 'https://example.test/cii-design-system/design-system/design/';
  assert.ok(current.includes('../archive/mapping-spec/#scope'));
  assert.equal(
    new URL('../archive/mapping-spec/#scope', `${base}mapping/`).href,
    `${base}archive/mapping-spec/#scope`
  );
  assert.equal(archive, '[Current](../../mapping/)');
});

test('examples remain literal while prose links are rewritten', () => {
  const sample = '[Product](./product-design-spec.md)';
  const examples = `\`\`\`svelte\n${sample}\n\`\`\`\n~~~md\n${sample}\n~~~\n\`${sample}\``;
  assert.equal(rewriteDocumentLinks(examples, 'mapping'), examples);
  assert.equal(
    rewriteDocumentLinks(`${examples}\n${sample}`, 'mapping'),
    `${examples}\n[Product](../product/)`
  );
});

test('unpublished document links fail generation instead of publishing broken links', () => {
  assert.throws(
    () => rewriteDocumentLinks('[Missing](./missing.md)', 'mapping'),
    /Unpublished document link/
  );
});
